    private fun _AXIOS_TAHN_2(): List<StaticItem> = listOf(
        StaticItem("Aspect Talisman", "This small talisman is finely crafted with\na metal base and some wooden inlay decorating\nthe talisman. Images of Cerridwen and Cernunnos\nare seen, holding an Oak sapling together in the\nmiddle of the talisman.\n★Game Moderator Approved★\nSigned by CosmicWhaleShark.", "minecraft:iron_ingot", ""),
