        StaticItem("Red Wine", "A vial of frothing, thick substance that is\ncrimson in color. It smells of rotting meat,\nand is probably something you don't want\nto drink.", "minecraft:potion", ""),
        StaticItem("Calaway Boost 350 \"Turtle Dove", "Brabant and Royalic came together to release\nthe Calaway Boost 350 \"Turtle Dove.\" 1588\n★Player Approved★\nSigned by Youngie5500.", "minecraft:chainmail_boots", ""),
