        StaticItem("Fancy Red Wall Carpet", "", "minecraft:banner", ""),
        StaticItem("Mirror", "A simple, yet effective mirror, with the\ncapabilities to reflect the visage of the\nviewer.\n★Game Moderator Approved★\nSigned by ImCookiie.", "minecraft:banner", ""),
        StaticItem("Popcorn", "Popcorn from PopcornLand (Vivian's House)\n★Player Approved★\nSigned by Popcorn Man.", "minecraft:wheat_seeds", ""),
