        StaticItem("Cactus Tea", "This tea makes you feel light.", "minecraft:potion", ""),
        StaticItem("Stuffed Lamb", "A pretty, lambshaped stuffed toy. It'd be\nmade mostly of wool, being extremely soft to\nthe touch, and nicely stuffed, to give it\nthat soft, comforting feel. The head had eye\npaterns sewn into for eyes, aswell as a\nsmile. Overal, a pretty toy for a young\nchild.\n★Game Moderator Approved★\nSigned by Ioannis.", "minecraft:wool", ""),
        StaticItem("Black Ferrum Warhammer", "Special Ability: Bone Break\n20% chance on full hit to cripple target.\n★Player Approved★\nSigned by Jualia Willow.", "minecraft:iron_pickaxe", ""),
