    private fun _AXIOS_TAHN_14(): List<StaticItem> = listOf(
        StaticItem("Sif Slayer", "A holy aurum weapon infused with Ascended\nSoul Fire. The fire would not burn a\nnon-tainted being, and the sword would act as\nnormal. However, for a tainted being it would\ncaught through it like butter!\n★Lore Moderator Approved★\nSigned by Whispess.", "minecraft:golden_sword", ""),
