        StaticItem("Tooth of a Corrupted Giant", "Snapped off of the maw of a corrupted stone\ngiant, the giant enamel plated would be dyed\na deep shade of red.\n★Event Actor Approved★\nSigned by Tahmas.", "minecraft:heavy_weighted_pressure_plate", ""),
