        StaticItem("Blue Orchid", "This plant shakes in your hands. A strange\npresence can be felt oozing off of it, like\nsomething is watching from it. Like its roots\nare hunting.\n★Event Actor Approved★\nSigned by Aesopian.", "minecraft:red_flower", ""),
