        StaticItem("Pendant of Malin", "", "minecraft:name_tag", ""),
        StaticItem("Mana Crystal", "*This mana crystal has been appropriate for\none function. That is to be used in arcane machina.*\n*Moderator Approved*\nBrandNewKitten approved this item.", "minecraft:stained_glass", ""),
        StaticItem("Ashwood Wand", "An ashwood wand of fine craftsmanship.\nParticular care taken to the handle with\nseveral beveled grooves lining it at equal\nspacing. The wand itself being finished off\nwith a basic silver end cap.", "minecraft:stick", ""),
        StaticItem("A Cute Kitty", "A simple kitty that was once found in a tree.\nIt enjoys the taste of various meats and\nfollows Laethesia around. Whether it'd due to\naffection or hoping for a warm meal, it is\nunknown. What is known is that it's simply\nadorable! Aww!\n★Event Actor Approved★\nSigned by SquirtGun.", "minecraft:skull", ""),
