    private fun _AXIOS_TAHN_15(): List<StaticItem> = listOf(
        StaticItem("-+- Steel Full Helm -+-", "An ordinary steel full helm with a vented\nvisor that could be raised and lowered via\nthe use of a pair of steel colored leather\nstraps bolted to the side of the helm.", "minecraft:iron_helmet", ""),
