        StaticItem("Four-Leaf Clover", "A pristine four-leaf clover, bearing an\nadditional leaf when compared to it's\ntraditional counter part, which holds only\nthree leaves. Giving off a polished, natural\natmosphere, this variety of clover is rather\nrare.", "minecraft:sapling", ""),
        StaticItem("Doll", "A doll with flaxen wool locks, draped in a\ncarefully sewn dress of pink fabric.\n★Game Moderator Approved★\nSigned by JVQ.", "minecraft:rabbit_hide", ""),
