        StaticItem("Orcish Helm", "An Orcish Helmet crafted during the War that\nnearly wiped out all the Orcs, it appears to\nbe one of the last remnants of The War Uzg\n★Player Approved★\nSigned by Marijuanaology.", "minecraft:iron_helmet", ""),
