    private fun _AXIOS_TAHN_18(): List<StaticItem> = listOf(
        StaticItem("Warmed Emerald", "An emerald, slightly warm to the touch.\nLooking into the verdant color reveals that\nit has a core of dancing green fire.\n★Player Approved★\nSigned by DiscoLiquid.", "minecraft:emerald", ""),
        StaticItem("Shard of Dworkin's Mirror", "A broken piece of unidentified material,\nlikely a shattered piece of a larger relic.\nThe shard has reflective qualities to it,\nperhaps earning it it’s name. Under different\nkinds of light the shard’s qualities change,\nreflecting different lined patterns within\nit’s face. The shard seems plain at first\nglance, though tells another story when\ntouched with bare skin...\n★Game Moderator Approved★\nSigned by Cablam.", "minecraft:dye", ""),
        StaticItem("Valorian Poleaxe", "A 6'5ft long poleaxe with a thick wooden\nhandle of which's end held the poleaxe head\nmade out of daemon steel. Letters V.A.L.O.R.\nwere carved into it's side.\n★Player Approved★\nSigned by Dewlox.", "minecraft:iron_axe", ""),
        StaticItem("Jewel-Edged Easterner Blade", "Special Ability: Sweeping Strike\nWhile standing still or sneaking deal small AoE damage", "minecraft:iron_sword", ""),
        StaticItem("Uteah Woodcarving", "This is an exceptionally-crafted Uteahwood\nmodel of the Uteah. It is decorated with naft\nmoss and oak resin.\n★Game Moderator Approved★\nSigned by Magicpastry.", "minecraft:sapling", ""),
        StaticItem("Golden Halberd", "A long shaft of wood at one end, at the other\nend of the shaft, the end pointed towards the\nenemy, a combination of three things existed.\nAt one side of the shaft’s other end, an axe\nblade was fitted and at the back of the axe\nblade, a useful hook was provided which was\nused to dislodge horsemen during combat. The\nstaff culminated in a sharpened pike which\nformed the third key aspect of the halberd.\n★Event Actor Approved★\nSigned by ClergyManDan.", "minecraft:golden_hoe", ""),
        StaticItem("WarAxe", "A crescent shape 5 inch long head with a\nsquare hammer opposite of the blade, 22 inch\nlong steel haft, the end of the haft unscrews\nto reveal a 5-inch slim blade. Heavily\npatinated head and handle with traces of\nengraving.\n★Event Actor Approved★\nSigned by ClergyManDan.", "minecraft:iron_axe", ""),
        StaticItem("Old Elven Coin", "A old and aged coin, covered in rust but\nappears to be an ancient piece of Axios.\n★Event Actor Approved★\nSigned by Shamanistic.", "minecraft:gold_nugget", ""),
        StaticItem("Sapphire Gem", "★Event Actor Approved★\nSigned by oncenoeda.", "minecraft:skull", ""),
        StaticItem("Black Arrow", "A long, black-tipped arrow coated with slime.\n★Event Actor Approved★\nSigned by _SurrenderMaine_.", "minecraft:arrow", ""),
        StaticItem("Eryn Serenes Arm", "", "minecraft:bone", ""),
        StaticItem("Child's hand", "A skeletal hand once belonging to a child,\nlikely long dead.\n★Event Actor Approved★\nSigned by oncenoeda.", "minecraft:bone", ""),
        StaticItem("Unlimited Tikcet", "With this ticket, show it to those who hold\nevents requiring tickets! Any amount or times\nyou can pass, you're good to go!\n★Player Approved★\nSigned by Imperial Administration.", "minecraft:book", ""),
        StaticItem("Cunt Cleaver", "The famed axe carried by an inbred goon", "minecraft:diamond_axe", ""),
        StaticItem("Iron Mace", "A child sized mace, this would weigh two\npounds. It has the name Rory carved into it's\nside in gold letters.", "minecraft:iron_axe", ""),
        StaticItem("The Golden Sun", "In your hand lies a beautiful piece of\njewelry. It'd be made out of pure gold,\nportraying a detailed sun with wavey rays\ncoming from it. The gold was polished to the\npoint where you could see your own reflection\nin it. This meant, that if light fell upon\nit, it truly seemed to be a shining sun.\nEmbedded right in the middle of the sun was a\ndiamond the size of a bird's egg. It was\nnicely polished, and shimmered if light fell\nupon it.\n★Game Moderator Approved★\nSigned by _Stigwig.", "minecraft:gold_ingot", ""),
        StaticItem("Sky God's Axe", "Special Ability: Shield Break\nDisable an opponents shield on successful hit.\n★Game Moderator Approved★\nSigned by _Stigwig.", "minecraft:iron_axe", ""),
        StaticItem("Giant Crab Meat", "Somewhat tough, and quite chewy. Has a gray\ntinge to it.\n★Event Actor Approved★\nSigned by Ebonsquire.", "minecraft:dye", ""),
        StaticItem("Ape Destroyer C3000", "A Weapon made by the gods and given to the\nbest ape killer.\n★Player Approved★\nSigned by W4saki.", "minecraft:iron_axe", ""),
        StaticItem("Krugmas Snow Plough!", "Shovel snow with super efficiency!\n*Moderator Approved*\nWretched approved this item.", "minecraft:iron_shovel", ""),
        StaticItem("Tribal Shortbow", "A very tribal-looking bow with aurum rings on\nthe wood of the bow. It seems to have words\nencrested in the wood reading \"Ufur-Ilzgûl,\nLûp-Ilzgûl!\". The string seems flexible while\nthe wood is sturdy.", "minecraft:bow", ""),
        StaticItem("Enhanced Aurum Arrows", "Aurum arrows enhanced with runes, made to\ndisable monsters and spooks.", "minecraft:arrow", ""),
