        StaticItem("Beaumonte Centennial", "A full-bodied and luxurious red wine made\nfrom Cabernet Sauvignon grapes. This bottle\nis marked with the vintage date of 1600.", "minecraft:potion", ""),
        StaticItem("Sweet Gloves", "A pair of white doe-skin gloves, with Eleanor\nAlexandra's initials embroidered with real\ngold thread on the corner of both. They are\nscented with lilac, rose, bergamot and orange\nblossom.\n★Player Approved★\nSigned by marinaemily.", "minecraft:leather", ""),
        StaticItem("Seax#", "A medium sized dagger with a single sharp\nedge. It tapers into a point.", "minecraft:diamond_sword", ""),
